// Agoda — best time to buy and sell stock (LeetCode 121), unlimited trades (122), with a fee (714).
public static class Stock {
    public static int MaxProfitOne(int[] prices) {
        if (prices == null || prices.Length == 0) return 0;
        int min = prices[0], best = 0;
        foreach (var p in prices) { min = Math.Min(min, p); best = Math.Max(best, p - min); }
        return best;
    }

    public static long MaxProfitUnlimited(int[] prices) {
        if (prices == null) return 0;
        long sum = 0;
        for (int i = 1; i < prices.Length; i++) if (prices[i] > prices[i - 1]) sum += prices[i] - prices[i - 1];
        return sum;
    }

    // Each completed buy+sell pays `fee` once. Two states: holding a share, or not.
    public static long MaxProfitWithFee(int[] prices, int fee) {
        if (prices == null || prices.Length == 0) return 0;
        if (fee < 0) throw new ArgumentOutOfRangeException(nameof(fee));
        long cash = 0, hold = -prices[0];
        for (int i = 1; i < prices.Length; i++) {
            long newCash = Math.Max(cash, hold + prices[i] - fee);
            hold = Math.Max(hold, cash - prices[i]);
            cash = newCash;
        }
        return cash;
    }
}
